# -*- coding: utf-8 -*-
# داشبورد جمعية أعمال التفاعلي | فريق آفاق
# التشغيل: pip install dash plotly pandas && python app.py
# ثم افتح الرابط الذي يظهر في الطرفية. للنشر عبر الإنترنت يلزم استضافة تطبيق Dash.

import pandas as pd
import plotly.graph_objects as go
from dash import Dash, dcc, html, Input, Output, State, ctx

DATA = [{"المجال": "عدد المستفيدين", "2024": 8885.0, "2025": 7964.0}, {"المجال": "فرص التطوع", "2024": 100.0, "2025": 365.0}, {"المجال": "عدد ساعات التطوع", "2024": 3426.0, "2025": 4900.0}, {"المجال": "المستفيدين من التمويل الجمعية", "2024": 850.0, "2025": 1119.0}, {"المجال": "اجمالي مبلغ التمويل", "2024": 24077650.0, "2025": 39321489.0}, {"المجال": "عدد مستفيدي مشروع طعيم", "2024": 10.0, "2025": 23.0}, {"المجال": "مستفيدي معمل الخياطة", "2024": 205.0, "2025": 45.0}, {"المجال": "مبادرة خطى أعمال", "2024": 780.0, "2025": 823.0}, {"المجال": "التمكين", "2024": 1712.0, "2025": 4875.0}, {"المجال": "مبادرة نبيه", "2024": 1013.0, "2025": 1004.0}, {"المجال": "نسبة الحوكمة", "2024": 95.0, "2025": 96.0}, {"المجال": "الإيرادات", "2024": 11267950.0, "2025": 11284976.0}, {"المجال": "المصروفات", "2024": 18623882.0, "2025": 12031790.0}]
LOGO_B64 = ""
df = pd.DataFrame(DATA)
YEARS = ["2024", "2025"]

# تصنيف تحليلي للمؤشرات لأغراض الفلترة وترتيب القصة
GROUPS = {
    "الأثر والمستفيدون": ["عدد المستفيدين", "عدد مستفيدي مشروع طعيم", "مستفيدي معمل الخياطة", "مبادرة خطى أعمال", "التمكين", "مبادرة نبيه"],
    "التمويل": ["المستفيدين من التمويل الجمعية", "اجمالي مبلغ التمويل"],
    "التطوع": ["فرص التطوع", "عدد ساعات التطوع"],
    "الحوكمة": ["نسبة الحوكمة"],
    "الإيرادات والمصروفات": ["الإيرادات", "المصروفات"],
}
COLORS = {"green":"#6FAF9B", "dark_green":"#347763", "pink":"#D994A2", "dark_pink":"#B96378", "navy":"#243B53", "blue":"#7397C8", "cream":"#F6F1E8", "grey":"#667085", "grid":"#E9EDF2", "white":"#FFFFFF"}
FONT = "Arial, Tahoma, sans-serif"

# Exact source labels, with flexible matching for common spelling variants
ALIASES = {
    "beneficiaries": ["عدد المستفيدين"],
    "funding_people": ["المستفيدين من التمويل الجمعية", "المستفيدين من التمويل"],
    "funding": ["اجمالي مبلغ التمويل", "إجمالي مبلغ التمويل"],
    "opportunities": ["فرص التطوع"],
    "hours": ["عدد ساعات التطوع"],
    "governance": ["نسبة الحوكمة"],
    "taeem": ["عدد مستفيدي مشروع طعيم", "مشروع طعيم"],
    "sewing": ["مستفيدي معمل الخياطة", "معمل الخياطة"],
    "khotaa": ["مبادرة خطى أعمال", "خطى أعمال"],
    "tamkeen": ["التمكين"],
    "nabeeh": ["مبادرة نبيه"],
    "revenue": ["الإيرادات", "الايرادات"],
    "expenses": ["المصروفات"],
}
def row_for(key):
    for alias in ALIASES[key]:
        found = df[df["المجال"].astype(str).str.strip().eq(alias)]
        if not found.empty:
            return found.iloc[0]
    for alias in ALIASES[key]:
        found = df[df["المجال"].astype(str).str.contains(alias, regex=False, na=False)]
        if not found.empty:
            return found.iloc[0]
    return None

def val(key, year):
    r = row_for(key)
    if r is None: return None
    v = r.get(year)
    return None if pd.isna(v) else float(v)

def fmt(v, money=False, pct=False):
    if v is None: return "—"
    if pct: return f"{v:,.0f}%"
    if money: return f"{v:,.0f} ريال"
    return f"{v:,.0f}"

def metric_label(key):
    names = {"beneficiaries":"إجمالي المستفيدين", "funding_people":"المستفيدون من التمويل", "funding":"إجمالي مبلغ التمويل", "opportunities":"فرص التطوع", "hours":"ساعات التطوع", "governance":"نسبة الحوكمة"}
    return names.get(key, key)

def filtered_years(selected):
    return selected if selected else YEARS

def group_for_metric(metric):
    for g, names in GROUPS.items():
        if metric in names: return g
    return ""

def make_fig(title, height=360):
    fig = go.Figure()
    fig.update_layout(
        title=dict(text=title, x=0.98, xanchor="right", font=dict(size=17, color=COLORS["navy"], family=FONT)),
        template="plotly_white", font=dict(family=FONT, size=12, color=COLORS["navy"]),
        height=height, margin=dict(l=20, r=30, t=65, b=40),
        paper_bgcolor=COLORS["white"], plot_bgcolor=COLORS["white"],
        hoverlabel=dict(bgcolor=COLORS["navy"], font_family=FONT, font_size=13),
        legend=dict(orientation="h", yanchor="bottom", y=1.01, xanchor="left", x=0, font=dict(size=11)),
        bargap=0.35, transition_duration=350
    )
    fig.update_xaxes(showgrid=False, showline=False, zeroline=False, automargin=True)
    fig.update_yaxes(showgrid=False, showticklabels=False, showline=False, zeroline=False, automargin=True)
    return fig

def chart_card(fig, chart_id):
    return html.Div(dcc.Graph(id=chart_id, figure=fig, config={"responsive": True, "displaylogo": False, "scrollZoom": False}), className="chart-card")

def selected_metric_names(group):
    if not group or group == "الكل": return set(df["المجال"].tolist())
    return set(GROUPS.get(group, []))

def group_visible(group, chart_group):
    return group in (None, "الكل") or group == chart_group

def make_cards(years, group):
    specs = [
        ("beneficiaries", "إجمالي المستفيدين", False, False, "الأثر والمستفيدون"),
        ("funding_people", "المستفيدون من التمويل", False, False, "التمويل"),
        ("funding", "إجمالي التمويل", True, False, "التمويل"),
        ("opportunities", "فرص التطوع", False, False, "التطوع"),
        ("hours", "ساعات التطوع", False, False, "التطوع"),
        ("governance", "نسبة الحوكمة", False, True, "الحوكمة"),
    ]
    cards=[]
    for key, title, money, pct, g in specs:
        if not group_visible(group, g): continue
        vals=[val(key,y) for y in years]
        vals=[v for v in vals if v is not None]
        if not vals: continue
        if len(years)==2 and val(key,"2024") is not None and val(key,"2025") is not None:
            a,b=val(key,"2024"),val(key,"2025")
            delta=b-a
            change=(delta/a*100) if a else None
            if change is None: change_text=""
            elif abs(change)<0.05: change_text="دون تغير ملحوظ"
            else: change_text=f"{'↑' if delta>0 else '↓'} {abs(change):.1f}% عن 2024"
            change_color=COLORS["dark_green"] if delta>=0 else COLORS["dark_pink"]
            value_text=fmt(b,money,pct)
            subtitle=f"2024: {fmt(a,money,pct)}  •  2025"
        else:
            y=years[-1]
            value_text=fmt(val(key,y),money,pct)
            change_text=f"القيمة المعروضة لعام {y}"
            change_color=COLORS["grey"]
            subtitle=""
        cards.append(html.Div([
            html.Div(title, className="kpi-title"),
            html.Div(value_text, className="kpi-value"),
            html.Div(change_text, className="kpi-change", style={"color":change_color}),
            html.Div(subtitle, className="kpi-subtitle") if subtitle else html.Div()
        ], className="kpi-card"))
    return cards

def create_charts(years, group):
    charts=[]
    def add(fig, id, g):
        if group_visible(group,g): charts.append(chart_card(fig,id))
    # 1. الوصول للمستفيدين
    yvals=[val("beneficiaries",y) for y in years]
    if any(v is not None for v in yvals):
        f=make_fig("إجمالي المستفيدين عبر العامين",350)
        f.add_trace(go.Bar(x=years,y=yvals,marker_color=[COLORS["green"] if y=="2024" else COLORS["pink"] for y in years],
                           text=[fmt(v) if v is not None else "" for v in yvals],textposition="inside",insidetextanchor="middle",
                           textfont=dict(color=COLORS["navy"],size=13),hovertemplate="السنة: %{x}<br>عدد المستفيدين: %{y:,.0f}<extra></extra>"))
        f.update_layout(showlegend=False)
        add(f,"chart-beneficiaries","الأثر والمستفيدون")
    # 2. برامج ومستفيدون — only exact source indicators
    prog_keys=[("taeem","أسر مشروع طعيم"),("sewing","مستفيدو معمل الخياطة"),("khotaa","مبادرة خطى أعمال"),("tamkeen","التمكين"),("nabeeh","مبادرة نبيه")]
    labels=[]; v24=[]; v25=[]
    for k,label in prog_keys:
        a,b=val(k,"2024"),val(k,"2025")
        if a is not None and b is not None:
            labels.append(label); v24.append(a); v25.append(b)
    if labels:
        f=make_fig("تغير أعداد المستفيدين في البرامج والمبادرات",430)
        for y,vals,color in [("2024",v24,COLORS["green"]),("2025",v25,COLORS["pink"])]:
            f.add_trace(go.Bar(name=y,y=labels,x=vals,orientation="h",marker_color=color,text=[fmt(v) for v in vals],textposition="inside",
                               insidetextanchor="middle",textfont=dict(color=COLORS["navy"],size=11),hovertemplate="%{y}<br>"+y+": %{x:,.0f}<extra></extra>"))
        f.update_layout(barmode="group",legend_title_text="السنة")
        f.update_xaxes(showticklabels=False)
        f.update_yaxes(showticklabels=True)
        add(f,"chart-programs","الأثر والمستفيدون")
    # 3. إجمالي التمويل
    vals=[val("funding",y) for y in years]
    if any(v is not None for v in vals):
        f=make_fig("إجمالي مبلغ التمويل",350)
        f.add_trace(go.Bar(x=years,y=vals,marker_color=[COLORS["blue"] if y=="2024" else COLORS["dark_green"] for y in years],
                           text=[fmt(v) for v in vals],textposition="inside",insidetextanchor="middle",textfont=dict(color=COLORS["white"],size=12),
                           hovertemplate="السنة: %{x}<br>إجمالي التمويل: %{y:,.0f} ريال<extra></extra>"))
        f.update_layout(showlegend=False)
        add(f,"chart-funding","التمويل")
    # 4. مستفيدو التمويل
    vals=[val("funding_people",y) for y in years]
    if any(v is not None for v in vals):
        f=make_fig("عدد المستفيدين من التمويل",350)
        f.add_trace(go.Bar(x=years,y=vals,marker_color=[COLORS["green"] if y=="2024" else COLORS["pink"] for y in years],
                           text=[fmt(v) for v in vals],textposition="inside",textfont=dict(color=COLORS["navy"],size=13),
                           hovertemplate="السنة: %{x}<br>المستفيدون: %{y:,.0f}<extra></extra>"))
        f.update_layout(showlegend=False)
        add(f,"chart-funding-people","التمويل")
    # 5. متوسط التمويل لكل مستفيد، derived metric
    a,b=val("funding","2024"),val("funding","2025")
    pa,pb=val("funding_people","2024"),val("funding_people","2025")
    avg={"2024":a/pa if a is not None and pa else None,"2025":b/pb if b is not None and pb else None}
    avg_vals=[avg[y] for y in years]
    if any(v is not None for v in avg_vals):
        f=make_fig("متوسط التمويل لكل مستفيد",350)
        f.add_trace(go.Scatter(x=years,y=avg_vals,mode="lines+markers+text",line=dict(color=COLORS["dark_green"],width=4),
                               marker=dict(size=12,color=COLORS["pink"],line=dict(color=COLORS["white"],width=2)),
                               text=[fmt(v,True) if v is not None else "" for v in avg_vals],textposition="top center",
                               hovertemplate="السنة: %{x}<br>متوسط التمويل: %{y:,.0f} ريال<extra></extra>"))
        f.update_layout(showlegend=False)
        add(f,"chart-average","التمويل")
    # 6. فرص التطوع وساعاته separate due to different units
    for key,title,g in [("opportunities","عدد الفرص التطوعية","التطوع"),("hours","إجمالي ساعات التطوع","التطوع")]:
        vals=[val(key,y) for y in years]
        if any(v is not None for v in vals):
            f=make_fig(title,320)
            f.add_trace(go.Bar(x=years,y=vals,marker_color=[COLORS["green"] if y=="2024" else COLORS["pink"] for y in years],
                               text=[fmt(v) if v is not None else "" for v in vals],textposition="inside",textfont=dict(color=COLORS["navy"],size=13),
                               hovertemplate="السنة: %{x}<br>القيمة: %{y:,.0f}<extra></extra>"))
            f.update_layout(showlegend=False)
            add(f,"chart-"+key,g)
    # 7. Governance
    vals=[val("governance",y) for y in years]
    if any(v is not None for v in vals):
        f=make_fig("نسبة الحوكمة",320)
        f.add_trace(go.Scatter(x=years,y=vals,mode="lines+markers+text",line=dict(color=COLORS["blue"],width=4),marker=dict(size=12,color=COLORS["dark_green"]),
                               text=[fmt(v,pct=True) if v is not None else "" for v in vals],textposition="top center",
                               hovertemplate="السنة: %{x}<br>نسبة الحوكمة: %{y:.0f}%<extra></extra>"))
        f.update_layout(showlegend=False)
        add(f,"chart-governance","الحوكمة")
    # 8. Revenue vs expenses
    rev=[val("revenue",y) for y in years]; exp=[val("expenses",y) for y in years]
    if any(v is not None for v in rev+exp):
        f=make_fig("مقارنة الإيرادات والمصروفات",390)
        f.add_trace(go.Bar(name="الإيرادات",x=years,y=rev,marker_color=COLORS["green"],text=[fmt(v) if v is not None else "" for v in rev],textposition="inside",textfont=dict(color=COLORS["navy"],size=11),hovertemplate="%{x}<br>الإيرادات: %{y:,.0f} ريال<extra></extra>"))
        f.add_trace(go.Bar(name="المصروفات",x=years,y=exp,marker_color=COLORS["pink"],text=[fmt(v) if v is not None else "" for v in exp],textposition="inside",textfont=dict(color=COLORS["navy"],size=11),hovertemplate="%{x}<br>المصروفات: %{y:,.0f} ريال<extra></extra>"))
        f.update_layout(barmode="group",legend_title_text="المؤشر")
        add(f,"chart-finance","الإيرادات والمصروفات")
        # 9. Difference, revenue minus expenses
        net=[(rev[i]-exp[i]) if rev[i] is not None and exp[i] is not None else None for i in range(len(years))]
        f=make_fig("الفرق الحسابي بين الإيرادات والمصروفات",330)
        f.add_trace(go.Bar(x=years,y=net,marker_color=[COLORS["dark_green"] if v is not None and v>=0 else COLORS["dark_pink"] for v in net],
                           text=[fmt(v,True) if v is not None else "" for v in net],textposition="inside",textfont=dict(color=COLORS["white"],size=12),
                           hovertemplate="السنة: %{x}<br>الإيرادات ناقص المصروفات: %{y:,.0f} ريال<extra></extra>"))
        f.add_hline(y=0,line_color=COLORS["navy"],line_width=1)
        f.update_layout(showlegend=False)
        add(f,"chart-net","الإيرادات والمصروفات")
    return charts

def make_summary(years, group):
    items=[]
    compare = len(years) == 2 and set(years) == set(YEARS)
    if group in (None,"الكل","الأثر والمستفيدون"):
        if compare:
            a,b=val("beneficiaries","2024"),val("beneficiaries","2025")
            if a is not None and b is not None:
                change=(b-a)/a*100 if a else 0
                items.append(f"إجمالي المستفيدين {'ارتفع' if change>0 else 'انخفض' if change<0 else 'لم يتغير'} بنسبة {abs(change):.1f}% بين 2024 و2025.")
        else:
            y=years[0]
            a=val("beneficiaries",y)
            if a is not None: items.append(f"إجمالي المستفيدين في {y}: {a:,.0f} مستفيد.")
    if group in (None,"الكل","التمويل"):
        if compare:
            a,b=val("funding","2024"),val("funding","2025")
            if a is not None and b is not None:
                change=(b-a)/a*100 if a else 0
                items.append(f"إجمالي التمويل {'ارتفع' if change>0 else 'انخفض' if change<0 else 'لم يتغير'} بنسبة {abs(change):.1f}% بين العامين.")
            a,b=val("funding_people","2024"),val("funding_people","2025")
            if a is not None and b is not None: items.append(f"تغير عدد المستفيدين من التمويل من {a:,.0f} إلى {b:,.0f} مستفيدًا.")
        else:
            y=years[0]
            a,b=val("funding",y),val("funding_people",y)
            if a is not None: items.append(f"إجمالي التمويل في {y}: {a:,.0f} ريال.")
            if b is not None: items.append(f"عدد المستفيدين من التمويل في {y}: {b:,.0f} مستفيدًا.")
    if group in (None,"الكل","التطوع"):
        if compare:
            a,b=val("opportunities","2024"),val("opportunities","2025")
            if a is not None and b is not None: items.append(f"تغير عدد الفرص التطوعية من {a:,.0f} إلى {b:,.0f} فرصة.")
            a,b=val("hours","2024"),val("hours","2025")
            if a is not None and b is not None: items.append(f"تغيرت ساعات التطوع من {a:,.0f} إلى {b:,.0f} ساعة.")
        else:
            y=years[0]
            a,b=val("opportunities",y),val("hours",y)
            if a is not None: items.append(f"الفرص التطوعية في {y}: {a:,.0f} فرصة.")
            if b is not None: items.append(f"ساعات التطوع في {y}: {b:,.0f} ساعة.")
    if group in (None,"الكل","الحوكمة"):
        if compare:
            a,b=val("governance","2024"),val("governance","2025")
            if a is not None and b is not None: items.append(f"تغيرت نسبة الحوكمة من {a:.0f}% إلى {b:.0f}%، بفارق {b-a:+.0f} نقطة مئوية.")
        else:
            y=years[0]; a=val("governance",y)
            if a is not None: items.append(f"نسبة الحوكمة في {y}: {a:.0f}%.")
    if group in (None,"الكل","الإيرادات والمصروفات"):
        for y in years:
            r,e=val("revenue",y),val("expenses",y)
            if r is not None and e is not None:
                diff=r-e
                items.append(f"في {y}: الإيرادات ناقص المصروفات = {diff:,.0f} ريال؛ وهو فرق حسابي وليس حكمًا محاسبيًا نهائيًا.")
    if not items: items=["لا توجد مؤشرات متاحة لهذا الاختيار في ملف البيانات."]
    return html.Ul([html.Li(x) for x in items], className="summary-list")

app = Dash(__name__, title="جمعية أعمال | مقارنة الأداء", update_title="جارٍ تحديث الداشبورد...")
app.index_string = '''<!DOCTYPE html><html lang="ar" dir="rtl"><head>{%metas%}<meta name="viewport" content="width=device-width, initial-scale=1"><title>{%title%}</title>{%favicon%}{%css%}<style>
:root{--green:#6FAF9B;--dark-green:#347763;--pink:#D994A2;--dark-pink:#B96378;--navy:#243B53;--blue:#7397C8;--cream:#F6F1E8;--grey:#667085;--grid:#E9EDF2;--white:#fff}
*{box-sizing:border-box}body{margin:0;background:#F7F9FB;color:var(--navy);font-family:Arial,Tahoma,sans-serif}#react-entry-point{width:100%}.page-shell{max-width:1500px;margin:0 auto;padding:22px 24px 18px}.main-header{display:flex;align-items:center;justify-content:space-between;gap:24px;background:#fff;border:1px solid #edf0f3;border-radius:18px;padding:22px 26px;box-shadow:0 4px 18px rgba(36,59,83,.04)}.header-title{flex:1;text-align:right}.brand-name{font-size:clamp(25px,3vw,34px);margin:0 0 8px;font-weight:800;color:var(--navy)}.dashboard-subtitle{font-size:clamp(13px,1.5vw,17px);line-height:1.8;color:var(--grey)}.association-logo{width:112px;height:100px;object-fit:contain;flex-shrink:0}.filters-panel{display:grid;grid-template-columns:minmax(180px,1fr) minmax(220px,1.4fr) auto;gap:14px;align-items:end;background:#fff;border:1px solid #edf0f3;border-radius:16px;padding:16px;margin:16px 0}.filter-field label{display:block;font-size:13px;font-weight:700;color:var(--navy);margin:0 0 7px}.filter-dropdown{font-family:Arial,Tahoma,sans-serif}.Select-control,.Select-menu-outer,.Select-value-label,.Select-placeholder{font-family:Arial,Tahoma,sans-serif!important}.reset-button{height:44px;border:0;border-radius:10px;padding:0 18px;background:var(--dark-green);color:white;font-family:inherit;font-weight:700;font-size:14px;cursor:pointer;transition:background .2s,transform .2s;white-space:nowrap}.reset-button:hover{background:#285e4d;transform:translateY(-1px)}.reset-icon{font-size:19px;margin-left:8px}.kpi-grid{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:12px;margin:14px 0 28px}.kpi-card{background:#fff;border:1px solid #edf0f3;border-top:4px solid var(--green);border-radius:15px;padding:16px 14px;min-width:0;box-shadow:0 3px 12px rgba(36,59,83,.035);transition:transform .2s,box-shadow .2s;animation:fadeIn .3s ease}.kpi-card:nth-child(even){border-top-color:var(--pink)}.kpi-card:hover{transform:translateY(-3px);box-shadow:0 8px 22px rgba(36,59,83,.09)}.kpi-title{font-size:13px;line-height:1.6;color:var(--grey);font-weight:700;min-height:40px}.kpi-value{font-size:clamp(18px,1.8vw,25px);font-weight:800;line-height:1.5;color:var(--navy);overflow-wrap:anywhere;margin:5px 0}.kpi-change{font-size:12px;font-weight:700;line-height:1.6;min-height:20px}.kpi-subtitle{font-size:10px;line-height:1.7;color:#8992a0;margin-top:4px}.section-heading{margin:22px 2px 12px}.section-title{font-size:clamp(20px,2.3vw,25px);margin:0 0 7px;color:var(--navy);font-weight:800}.section-description{font-size:13px;line-height:1.8;color:var(--grey);margin:0}.charts-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:16px}.chart-card{background:#fff;border:1px solid #edf0f3;border-radius:16px;padding:8px 8px 2px;min-width:0;box-shadow:0 3px 12px rgba(36,59,83,.025);overflow:hidden}.chart-card .js-plotly-plot,.chart-card .plot-container{width:100%!important}.executive-section{margin:26px 0 22px}.summary-box{background:#fff;border:1px solid #e9eef1;border-right:5px solid var(--dark-green);border-radius:15px;padding:20px 24px;box-shadow:0 3px 12px rgba(36,59,83,.025)}.summary-list{padding-right:20px;margin:0;line-height:2.1;font-size:14px}.summary-list li{padding:2px 0 5px}.main-footer{margin-top:24px;background:var(--navy);color:white;border-radius:16px;padding:22px 20px;text-align:center}.team-title{font-size:16px;font-weight:800;margin-bottom:14px}.team-members{display:flex;justify-content:center;flex-wrap:wrap;gap:9px}.team-member{border:1px solid rgba(255,255,255,.25);background:rgba(255,255,255,.08);border-radius:30px;padding:8px 15px;font-size:13px}@keyframes fadeIn{from{opacity:.5;transform:translateY(4px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:1100px){.kpi-grid{grid-template-columns:repeat(3,minmax(0,1fr))}.page-shell{padding:16px}.charts-grid{gap:12px}}
@media(max-width:700px){.page-shell{padding:10px}.main-header{padding:16px;gap:10px;border-radius:14px}.association-logo{width:76px;height:72px}.brand-name{font-size:24px}.dashboard-subtitle{font-size:12px}.filters-panel{grid-template-columns:1fr;gap:12px;padding:13px}.reset-button{width:100%}.kpi-grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;margin-bottom:20px}.kpi-card{padding:12px 10px}.kpi-title{font-size:12px;min-height:36px}.kpi-value{font-size:19px}.kpi-change{font-size:11px}.charts-grid{grid-template-columns:1fr;gap:12px}.chart-card{padding:4px}.summary-box{padding:15px}.summary-list{font-size:13px}.team-member{font-size:12px;padding:7px 11px}}
</style></head><body>{%app_entry%}<footer>{%config%}{%scripts%}{%renderer%}</footer></body></html>'''

app.layout = html.Div([
    html.Header([
        html.Div([
            html.H1("جمعية أعمال", className="brand-name"),
            html.Div("لوحة تحليلية لمقارنة أداء الجمعية لعامي 2024 و2025", className="dashboard-subtitle")
        ], className="header-title"),
        html.Img(src="data:image/png;base64,"+LOGO_B64, className="association-logo", alt="شعار جمعية أعمال")
    ], className="main-header"),
    html.Section([
        html.Div([html.Label("السنة", htmlFor="year-filter"), dcc.Dropdown(id="year-filter", options=[{"label":"2024","value":"2024"},{"label":"2025","value":"2025"}], value=YEARS, multi=True, clearable=False, className="filter-dropdown")], className="filter-field"),
        html.Div([html.Label("المجال", htmlFor="group-filter"), dcc.Dropdown(id="group-filter", options=[{"label":"جميع المجالات","value":"الكل"}]+[{"label":g,"value":g} for g in GROUPS], value="الكل", clearable=False, className="filter-dropdown")], className="filter-field"),
        html.Button([html.Span("↺", className="reset-icon"), "إعادة تعيين"], id="reset-filters", n_clicks=0, className="reset-button")
    ], className="filters-panel"),
    html.Section(id="kpi-cards", className="kpi-grid"),
    html.Section(id="story-heading", className="section-heading"),
    html.Section(id="charts-container", className="charts-grid"),
    html.Section([
        html.H2("الملخص التنفيذي", className="section-title"),
        html.Div(id="executive-summary", className="summary-box")
    ], className="executive-section"),
    html.Footer([
        html.Div("تنفيذ فريق آفاق", className="team-title"),
        html.Div([html.Span(n, className="team-member") for n in ["أمجاد السواط","رندا المكتوم","جود الكريديس","نوره العماري"]], className="team-members")
    ], className="main-footer")
], className="page-shell")

@app.callback(
    Output("year-filter","value"), Output("group-filter","value"),
    Input("reset-filters","n_clicks"), prevent_initial_call=True
)
def reset_filters(_):
    return YEARS, "الكل"

@app.callback(
    Output("kpi-cards","children"), Output("charts-container","children"),
    Output("executive-summary","children"), Output("story-heading","children"),
    Input("year-filter","value"), Input("group-filter","value")
)
def update_dashboard(years, group):
    years=filtered_years(years)
    group=group or "الكل"
    cards=make_cards(years,group)
    charts=create_charts(years,group)
    heading=html.Div([
        html.H2("القصة التحليلية للأداء", className="section-title"),
        html.P("الأثر والمستفيدون ← التمويل ← التطوع والحوكمة ← الوضع المالي" if group=="الكل" else f"المجال المحدد: {group}", className="section-description")
    ])
    return cards, charts, make_summary(years,group), heading

app.layout.children[0].children[0].children[0] if False else None

app.css.append if False else None

if __name__ == "__main__":
    import os

if __name__ == "__main__":
    port = int(os.environ.get("PORT", 8050))
    app.run(debug=False, host="0.0.0.0", port=port)
